@p206_dataclass
class p206_SchedulerState(p206_ParamsBase):
    _pipeline: cutlass.pipeline.PipelineAsync
    _consumer_state: p206_PipelineState
    _producer_state: p206_PipelineState

    def consumer_wait(self, *, loc=None, ip=None):
        self._pipeline.consumer_wait(self._consumer_state, loc=loc, ip=ip)

    def consumer_release(self, *, loc=None, ip=None):
        self._pipeline.consumer_release(self._consumer_state, loc=loc, ip=ip)
        self._consumer_state.advance(loc=loc, ip=ip)

    def advance_consumer_state(self, *, loc=None, ip=None):
        self._consumer_state.advance(loc=loc, ip=ip)

    def producer_tail(self, *, loc=None, ip=None):
        self._pipeline.producer_tail(self._producer_state, loc=loc, ip=ip)


class p206_SingleTileLPTScheduler:

    @p206_dataclass
    class Params(p206_ParamsBase):
        total_blocks: Int32
        num_splits: Int32
        num_block: Int32
        num_head: Int32
        num_batch: Int32
        l2_minor: Int32
        num_head_divmod: p206_FastDivmodDivisor
        l2_minor_divmod: p206_FastDivmodDivisor
        l2_major_divmod: p206_FastDivmodDivisor
        l2_minor_residual_divmod: p206_FastDivmodDivisor
        num_hb_quotient: Int32
        num_splits_divmod: p206_FastDivmodDivisor
        is_split_kv: cutlass.Constexpr[bool] = False
        cluster_shape_m: cutlass.Constexpr[int] = 1
        scheduling_mode: cutlass.Constexpr[p206_SchedulingMode] = p206_SchedulingMode.STATIC
        lpt: cutlass.Constexpr[bool] = True
        use_cluster_idx: cutlass.Constexpr[bool] = True
        num_splits_dynamic_ptr: p206_Optional[cute.Tensor] = None

        @staticmethod
        @cute.jit
        def create(args: p206_TileSchedulerArguments, *, scheduling_mode: p206_SchedulingMode=p206_SchedulingMode.STATIC, loc=None, ip=None) -> 'p206_SingleTileLPTScheduler.Params':
            assert scheduling_mode in (p206_SchedulingMode.STATIC, p206_SchedulingMode.CLC), f'Only STATIC and CLC are supported, got {scheduling_mode!r}'
            size_one_kv_head = cutlass.Int64(args.seqlen_k) * (args.headdim + args.headdim_v) * args.element_size
            size_one_head = size_one_kv_head
            size_l2 = 50 * 1024 * 1024
            log2_floor = lambda n: 31 - p206_clz(n)
            swizzle = 1 if size_l2 < size_one_head else 1 << log2_floor(Int32(size_l2 // size_one_head))
            num_hb_quotient = args.num_head * args.num_batch // swizzle
            num_hb_remainder = args.num_head * args.num_batch % swizzle
            return p206_SingleTileLPTScheduler.Params(total_blocks=args.num_block * args.num_head * args.num_batch, num_block=args.num_block, num_head=args.num_head, num_batch=args.num_batch, l2_minor=Int32(swizzle), num_head_divmod=p206_FastDivmodDivisor(args.num_head), l2_minor_divmod=p206_FastDivmodDivisor(swizzle), l2_major_divmod=p206_FastDivmodDivisor(swizzle * args.num_block), l2_minor_residual_divmod=p206_FastDivmodDivisor(max(num_hb_remainder, 1)), num_hb_quotient=Int32(num_hb_quotient), num_splits=args.num_splits, num_splits_divmod=p206_FastDivmodDivisor(args.num_splits), is_split_kv=args.is_split_kv, cluster_shape_m=args.cluster_shape_mn[0], scheduling_mode=scheduling_mode, lpt=args.lpt, use_cluster_idx=args.use_cluster_idx, num_splits_dynamic_ptr=args.num_splits_dynamic_ptr)

    def __init__(self, params: Params, tile_idx: Int32, split_idx: Int32, ctx: p206_SchedulerState | None=None, *, loc=None, ip=None):
        self.params = params
        self._tile_idx = tile_idx
        self._split_idx = split_idx
        self._ctx = ctx
        self._loc = loc
        self._ip = ip

    @staticmethod
    def to_underlying_arguments(args: p206_TileSchedulerArguments, *, scheduling_mode: p206_SchedulingMode=p206_SchedulingMode.STATIC, loc=None, ip=None) -> Params:
        return p206_SingleTileLPTScheduler.Params.create(args, scheduling_mode=scheduling_mode, loc=loc, ip=ip)

    @staticmethod
    @cute.jit
    def create(params: Params, ctx: p206_SchedulerState | None=None, *, loc=None, ip=None) -> 'p206_SingleTileLPTScheduler':
        if const_expr(params.scheduling_mode == p206_SchedulingMode.CLC):
            return p206_SingleTileLPTScheduler(params, cute.arch.block_idx()[0], Int32(0), ctx, loc=loc, ip=ip)
        tile_idx, split_idx, _ = cute.arch.block_idx()
        return p206_SingleTileLPTScheduler(params, tile_idx, split_idx, loc=loc, ip=ip)

    @staticmethod
    def get_grid_shape(params: Params, *, loc=None, ip=None) -> p206_Tuple[Int32, Int32, Int32]:
        if const_expr(params.scheduling_mode == p206_SchedulingMode.CLC):
            return p206_SingleTileLPTScheduler._clc_grid_shape(params)
        return (params.total_blocks, params.num_splits, Int32(1))

    @cute.jit
    def get_current_work(self, *, loc=None, ip=None) -> p206_WorkTileInfo:
        if const_expr(self.params.scheduling_mode == p206_SchedulingMode.CLC):
            work = self._ctx.get_current_work()
            self._tile_idx = work.tile_idx[0]
            return self.clc_work_to_coords(work)
        params = self.params
        bidhb, l2_mod = divmod(self._tile_idx, params.l2_major_divmod)
        block, bidhb_residual = (0, 0)
        if bidhb < params.num_hb_quotient:
            block, bidhb_residual = divmod(l2_mod, params.l2_minor_divmod)
        else:
            block, bidhb_residual = divmod(l2_mod, params.l2_minor_residual_divmod)
        bidhb_actual = bidhb * params.l2_minor + bidhb_residual
        batch_idx, head_idx = divmod(bidhb_actual, params.num_head_divmod)
        if const_expr(params.lpt):
            block = params.num_block - 1 - block
        is_valid = self._tile_idx < params.total_blocks
        split_idx = self._split_idx
        if const_expr(params.is_split_kv and params.num_splits_dynamic_ptr is not None):
            if is_valid:
                num_splits = Int32(params.num_splits_dynamic_ptr[batch_idx])
                split_idx = split_idx | num_splits << 16
        return p206_WorkTileInfo((Int32(block), Int32(head_idx), Int32(batch_idx), Int32(split_idx)), is_valid)

    @cute.jit
    def initial_work_tile_info(self, *, loc=None, ip=None):
        if const_expr(self.params.scheduling_mode == p206_SchedulingMode.CLC):
            work = self._ctx.initial_work_tile_info()
            self._tile_idx = work.tile_idx[0]
            return self.clc_work_to_coords(work)
        return self.get_current_work(loc=loc, ip=ip)

    def prefetch_next_work(self, *, loc=None, ip=None):
        if const_expr(self.params.scheduling_mode == p206_SchedulingMode.CLC):
            self._ctx.prefetch_next_work(loc=loc, ip=ip)

    def advance_to_next_work(self, *, loc=None, ip=None):
        if const_expr(self.params.scheduling_mode == p206_SchedulingMode.CLC):
            self._ctx.consumer_wait(loc=loc, ip=ip)
            work = self.get_current_work()
            self._ctx.consumer_release(loc=loc, ip=ip)
            return work
        self._tile_idx = self.params.total_blocks
        return self.get_current_work()

    def producer_tail(self, *, loc=None, ip=None):
        if const_expr(self.params.scheduling_mode == p206_SchedulingMode.CLC):
            self._ctx.producer_tail(loc=loc, ip=ip)

    def __extract_mlir_values__(self):
        values, self._values_pos = ([], [])
        objs = [self.params, self._tile_idx, self._split_idx]
        if const_expr(self.params.scheduling_mode == p206_SchedulingMode.CLC):
            objs += [self._ctx]
        for obj in objs:
            obj_values = cutlass.extract_mlir_values(obj)
            values += obj_values
            self._values_pos.append(len(obj_values))
        return values

    def __new_from_mlir_values__(self, values):
        obj_list = []
        objs = [self.params, self._tile_idx, self._split_idx]
        if const_expr(self.params.scheduling_mode == p206_SchedulingMode.CLC):
            objs += [self._ctx]
        for obj, n_items in zip(objs, self._values_pos):
            obj_list.append(cutlass.new_from_mlir_values(obj, values[:n_items]))
            values = values[n_items:]
        return self.__class__(*obj_list, loc=self._loc)


class p206_FlashAttentionForwardBase:

    def __init__(self, dtype: p206_Type[cutlass.Numeric], head_dim: int, head_dim_v: p206_Optional[int]=None, qhead_per_kvhead: int=1, is_causal: bool=False, is_local: bool=False, pack_gqa: bool=True, tile_m: int=128, tile_n: int=128, num_stages: int=1, num_threads: int=128, Q_in_regs: bool=False, score_mod: p206_Optional[cutlass.Constexpr]=None, mask_mod: p206_Optional[cutlass.Constexpr]=None, has_aux_tensors: bool=False, q_subtile_factor: int=1, output_quant_key: p206_Optional[cutlass.Constexpr[str]]=None):
        self.dtype = dtype
        self.o_dtype = dtype
        hdim_multiple_of = 16
        self.tile_hdim = int(p206_math.ceil(head_dim / hdim_multiple_of) * hdim_multiple_of)
        head_dim_v = head_dim_v if head_dim_v is not None else head_dim
        self.same_hdim_kv = head_dim == head_dim_v
        self.tile_hdimv = int(p206_math.ceil(head_dim_v / hdim_multiple_of) * hdim_multiple_of)
        self.check_hdim_oob = head_dim != self.tile_hdim
        self.check_hdim_v_oob = head_dim_v != self.tile_hdimv
        self.qhead_per_kvhead = qhead_per_kvhead
        self.is_causal = is_causal
        self.is_local = is_local
        self.pack_gqa = pack_gqa
        self.tile_m = tile_m
        self.tile_n = tile_n
        self.num_threads = num_threads
        self.num_stages = num_stages
        self.q_subtile_factor = q_subtile_factor
        self.Q_in_regs = Q_in_regs
        self.score_mod = score_mod
        self.mask_mod = mask_mod
        self.output_quant_key = output_quant_key
        self.qk_acc_dtype = Float32
        self.score_vec_size: cutlass.Constexpr = getattr(score_mod, '__vec_size__', 1 if cutlass.const_expr(has_aux_tensors) else 2)
        if self.score_vec_size > 2:
            raise ValueError(f'score_mod vec_size {self.score_vec_size} not supported on Sm80/90/120 due to accumulator thread ownership pattern.')
        self.mask_vec_size: cutlass.Constexpr = getattr(mask_mod, '__vec_size__', 1)
        if self.mask_vec_size > 1:
            raise ValueError(f'mask_mod vec_size {self.mask_vec_size} not supported on Sm80/90/120 due to accumulator thread ownership pattern.')
        self.arch = p206_BaseDSL._get_dsl().get_arch_enum()

    def _setup_attributes(self):
        sQ_layout_atom, sK_layout_atom, sV_layout_atom, sO_layout_atom, sP_layout_atom = self._get_smem_layout_atom()
        self.sQ_layout = cute.tile_to_shape(sQ_layout_atom, (self.tile_m, self.tile_hdim), (0, 1))
        self.sK_layout = cute.tile_to_shape(sK_layout_atom, (self.tile_n, self.tile_hdim, self.num_stages), (0, 1, 2))
        self.sV_layout = cute.tile_to_shape(sV_layout_atom, (self.tile_n, self.tile_hdimv, self.num_stages), (0, 1, 2))
        self.sO_layout = cute.tile_to_shape(sO_layout_atom, (self.tile_m, self.tile_hdimv), (0, 1))
        if const_expr(sP_layout_atom is not None):
            self.sP_layout = cute.tile_to_shape(sP_layout_atom, (self.tile_m, self.tile_n), (0, 1))
        else:
            self.sP_layout = None
        universal_copy_bits = 128
        async_copy_elems = universal_copy_bits // self.dtype.width
        o_copy_elems = universal_copy_bits // self.o_dtype.width
        atom_async_copy = cute.make_copy_atom(p206_cpasync.CopyG2SOp(cache_mode=p206_cpasync.LoadCacheMode.GLOBAL), self.dtype, num_bits_per_copy=universal_copy_bits)
        atom_universal_copy = cute.make_copy_atom(cute.nvgpu.CopyUniversalOp(), self.o_dtype, num_bits_per_copy=universal_copy_bits)
        tQK_shape_dim_1 = sQ_layout_atom.outer.shape[1] // async_copy_elems
        assert self.num_Q_load_threads % tQK_shape_dim_1 == 0, 'num_threads must be divisible by tQK_shape_dim_1'
        assert self.num_producer_threads % tQK_shape_dim_1 == 0, 'num_threads must be divisible by tQK_shape_dim_1'
        tQ_layout = cute.make_ordered_layout((self.num_Q_load_threads // tQK_shape_dim_1, tQK_shape_dim_1), order=(1, 0))
        tK_layout = cute.make_ordered_layout((self.num_producer_threads // tQK_shape_dim_1, tQK_shape_dim_1), order=(1, 0))
        assert self.tile_m % tQ_layout.shape[0] == 0
        tV_shape_dim_1 = sV_layout_atom.outer.shape[1] // async_copy_elems
        tV_layout = cute.make_ordered_layout((self.num_producer_threads // tV_shape_dim_1, tV_shape_dim_1), order=(1, 0))
        tO_shape_dim_1 = sO_layout_atom.outer.shape[1] // o_copy_elems
        tO_layout = cute.make_ordered_layout((self.num_epilogue_threads // tO_shape_dim_1, tO_shape_dim_1), order=(1, 0))
        assert self.tile_m % tO_layout.shape[0] == 0
        vQKV_layout = cute.make_layout((1, async_copy_elems))
        vO_layout = cute.make_layout((1, o_copy_elems))
        self.gmem_tiled_copy_Q = cute.make_tiled_copy_tv(atom_async_copy, tQ_layout, vQKV_layout)
        self.gmem_tiled_copy_K = cute.make_tiled_copy_tv(atom_async_copy, tK_layout, vQKV_layout)
        self.gmem_tiled_copy_V = cute.make_tiled_copy_tv(atom_async_copy, tV_layout, vQKV_layout)
        self.gmem_tiled_copy_O = cute.make_tiled_copy_tv(atom_universal_copy, tO_layout, vO_layout)

    @cute.jit
    def epilogue(self, acc_O: cute.Tensor, lse: cute.Tensor, mO: cute.Tensor, mLSE: p206_Optional[cute.Tensor], sO: cute.Tensor, seqlen: p206_SeqlenInfoQK, gmem_tiled_copy_O: cute.TiledCopy, tma_atom_O: p206_Optional[cute.CopyAtom], tiled_mma: cute.TiledMma, tidx: Int32, m_block: Int32, head_idx: Int32, batch_idx: Int32, split_idx: Int32=Int32(0)):
        cO = cute.make_identity_tensor((self.tile_m, self.tile_hdimv))
        pack_gqa = p206_PackGQA(self.tile_m, self.tile_hdimv, self.check_hdim_v_oob, self.qhead_per_kvhead)
        if const_expr(not self.is_split_kv):
            rO = cute.make_fragment_like(acc_O, self.o_dtype)
            rO.store(acc_O.load().to(self.o_dtype))
            cute.arch.barrier(barrier_id=int(p206_NamedBarrierFwd.Epilogue), number_of_threads=self.num_epilogue_threads)
            smem_copy_atom_O = p206_m_utils.get_smem_store_atom(self.arch.major * 10 + self.arch.minor, self.o_dtype)
            smem_thr_copy_O = cute.make_tiled_copy_C(smem_copy_atom_O, tiled_mma).get_slice(tidx)
            taccOrO = smem_thr_copy_O.retile(rO)
            taccOsO = smem_thr_copy_O.partition_D(sO)
            cute.copy(smem_copy_atom_O, taccOrO, taccOsO)
        if const_expr(mLSE is not None):
            if const_expr(self.is_split_kv):
                mLSE_cur = seqlen.offset_batch_Q(mLSE, batch_idx, dim=2)[None, head_idx, split_idx]
            else:
                mLSE_cur = seqlen.offset_batch_Q(mLSE, batch_idx, dim=2)[None, head_idx]
            if const_expr(not self.pack_gqa):
                gLSE = cute.local_tile(mLSE_cur, (self.tile_m,), (m_block,))
                gLSE_expanded_layout = cute.append(gLSE.layout, cute.make_layout((self.tile_hdimv,), stride=(0,)))
                gLSE_expanded = cute.make_tensor(gLSE.iterator, gLSE_expanded_layout)
                thr_mma = tiled_mma.get_slice(tidx)
                taccOgLSE = p206_layout_utils.reshape_acc_to_mn(thr_mma.partition_C(gLSE_expanded))
                assert cute.size(taccOgLSE, mode=[0]) == cute.size(lse)
                taccOcO = p206_layout_utils.reshape_acc_to_mn(thr_mma.partition_C(cO))
                t0accOcO = p206_layout_utils.reshape_acc_to_mn(thr_mma.get_slice(0).partition_C(cO))
                if taccOcO[0][1] == 0:
                    for m in cutlass.range(cute.size(taccOgLSE.shape[1]), unroll_full=True):
                        if t0accOcO[m, 0][0] < seqlen.seqlen_q - m_block * self.tile_m - taccOcO[0][0]:
                            taccOgLSE[m, 0] = lse[m]
            else:
                pack_gqa.store_LSE(mLSE_cur, lse, tiled_mma, tidx, m_block, seqlen.seqlen_q)
        ragged = self.use_tma_O and (seqlen.has_cu_seqlens_q or seqlen.has_seqused_q)
        if const_expr(self.is_split_kv):
            mO_cur = seqlen.offset_batch_Q(mO, batch_idx, dim=3)[None, None, head_idx, split_idx]
        else:
            mO_cur = seqlen.offset_batch_Q(mO, batch_idx, dim=3, ragged=ragged)[None, None, head_idx]
        if const_expr(self.is_split_kv):
            cute.arch.barrier(barrier_id=int(p206_NamedBarrierFwd.Epilogue), number_of_threads=self.num_epilogue_threads)
            if const_expr(not self.pack_gqa):
                gO = cute.local_tile(mO_cur, (self.tile_m, self.tile_hdimv), (m_block, 0))
                thr_mma = tiled_mma.get_slice(tidx)
                taccOgO = p206_layout_utils.reshape_acc_to_mn(thr_mma.partition_C(gO))
                taccOcO = p206_layout_utils.reshape_acc_to_mn(thr_mma.partition_C(cO))
                taccOrO = p206_layout_utils.reshape_acc_to_mn(acc_O)
                seqlen_q_limit = seqlen.seqlen_q - m_block * self.tile_m
                for k in cutlass.range_constexpr(cute.size(taccOrO.shape[0])):
                    if taccOcO[k, 0][0] < seqlen_q_limit:
                        for m in cutlass.range_constexpr(cute.size(taccOrO.shape[1])):
                            if const_expr(not self.check_hdim_v_oob) or taccOcO[k, m][1] < mO.shape[1]:
                                taccOgO[k, m] = taccOrO[k, m]
            else:
                if const_expr(not seqlen.has_cu_seqlens_q):
                    mO_gqa = mO[None, None, None, batch_idx, split_idx]
                else:
                    offset = (0, seqlen.offset_q)
                    mO_gqa = cute.domain_offset((offset, 0, 0), mO[None, None, None, split_idx])
                pack_gqa.store_O_splitkv(mO_gqa, acc_O, tiled_mma, tidx, m_block, seqlen.seqlen_q, head_idx)
        elif const_expr(self.use_tma_O):
            cute.arch.fence_view_async_shared()
            cute.arch.barrier_arrive(barrier_id=int(p206_NamedBarrierFwd.Epilogue), number_of_threads=self.num_epilogue_threads + cute.arch.WARP_SIZE)
            gO = cute.local_tile(mO_cur, (self.tile_m, self.tile_hdimv), (m_block, 0))
            store_O, _, _ = p206_copy_utils.tma_get_copy_fn(tma_atom_O, 0, cute.make_layout(1), sO, gO, single_stage=True)
            warp_idx = cute.arch.make_warp_uniform(cute.arch.warp_idx())
            if warp_idx == 4:
                cute.arch.barrier(barrier_id=int(p206_NamedBarrierFwd.Epilogue), number_of_threads=self.num_epilogue_threads + cute.arch.WARP_SIZE)
                store_O()
                cute.arch.cp_async_bulk_commit_group()
                cute.arch.cp_async_bulk_wait_group(0, read=True)
        else:
            cute.arch.barrier(barrier_id=int(p206_NamedBarrierFwd.Epilogue), number_of_threads=self.num_epilogue_threads)
            gmem_thr_copy_O = gmem_tiled_copy_O.get_slice(tidx)
            tOsO = gmem_thr_copy_O.partition_S(sO)
            tOrO = cute.make_fragment_like(tOsO, self.o_dtype)
            cute.autovec_copy(tOsO, tOrO)
            if const_expr(not self.pack_gqa):
                gO = cute.local_tile(mO_cur, (self.tile_m, self.tile_hdimv), (m_block, 0))
                tOgO = gmem_thr_copy_O.partition_D(gO)
                tOcO = gmem_thr_copy_O.partition_S(cO)
                t0OcO = gmem_tiled_copy_O.get_slice(0).partition_S(cO)
                tOpO = p206_m_utils.predicate_k(tOcO, limit=mO.shape[1])
                for rest_m in cutlass.range_constexpr(cute.size(tOrO.shape[1])):
                    if t0OcO[0, rest_m, 0][0] < seqlen.seqlen_q - m_block * self.tile_m - tOcO[0][0]:
                        cute.copy(gmem_tiled_copy_O, tOrO[None, rest_m, None], tOgO[None, rest_m, None], pred=tOpO[None, rest_m, None] if const_expr(self.check_hdim_v_oob) else None)
            else:
                pack_gqa.store_O(mO_cur, tOrO, gmem_tiled_copy_O, tidx, m_block, seqlen.seqlen_q)


class p206_FlashAttentionForwardSm90(p206_FlashAttentionForwardBase):

    def __init__(self, *args, intra_wg_overlap: bool=True, mma_pv_is_rs: bool=True, paged_kv_non_tma: bool=False, is_split_kv: bool=False, kv_dtype=None, fp8_kv_dequant: bool=False, native_fp8: bool=False, native_fp8_o_dtype=None, native_fp8_tma_box_n: p206_Optional[int]=None, native_fp8_direct_3d_grid: bool=False, native_fp8_ctas_per_sm: int=1, **kwargs):
        super().__init__(*args, **kwargs)
        assert self.output_quant_key is None, 'Fused quant output not implemented for FlashAttentionForwardSm90'
        self.native_fp8 = native_fp8
        self.direct_3d_grid = native_fp8 and native_fp8_direct_3d_grid
        self.ctas_per_sm = native_fp8_ctas_per_sm if native_fp8 else 1
        assert (native_fp8_o_dtype is not None) == self.native_fp8, 'native_fp8_o_dtype must be supplied exactly when native_fp8 is enabled'
        if self.native_fp8:
            assert native_fp8_o_dtype in (p206_Float16, p206_BFloat16), 'native_fp8_o_dtype must be Float16 or BFloat16'
            self.o_dtype = native_fp8_o_dtype
        self.intra_wg_overlap = intra_wg_overlap and (not self.native_fp8)
        self.mma_pv_is_rs = mma_pv_is_rs
        self.buffer_align_bytes = 1024
        self.use_tma_KV = not paged_kv_non_tma
        self.tma_box_n = native_fp8_tma_box_n
        assert self.tma_box_n is None or (self.native_fp8 and self.use_tma_KV and (self.tile_n % self.tma_box_n == 0) and (self.tile_n // self.tma_box_n <= cute.arch.WARP_SIZE))
        self.kv_boxes_per_tile = 1 if self.tma_box_n is None else self.tile_n // self.tma_box_n
        self.is_split_kv = is_split_kv
        self.fp8_kv_dequant = fp8_kv_dequant
        assert not (self.native_fp8 and self.fp8_kv_dequant), 'native_fp8 and fp8_kv_dequant are mutually exclusive'
        assert not self.native_fp8 or self.dtype == p206_Float8E4M3FN, 'native_fp8 requires E4M3 Q/K/V compute operands'
        assert not self.native_fp8 or (self.mma_pv_is_rs and (not self.Q_in_regs) and ((self.tile_hdim, self.tile_hdimv) in ((64, 64), (96, 96), (128, 128), (192, 192), (256, 256), (192, 128))) and (self.tile_n % 32 == 0)), 'native_fp8 supports RS PV, separate Q/V shared storage, head dimensions {64,96,128,192,256} equal or (192,128), and tile_n divisible by 32'
        self.kv_dtype = kv_dtype if kv_dtype is not None else self.dtype
        assert self.use_tma_KV or not (self.check_hdim_oob or self.check_hdim_v_oob), 'Paged KV does not support irregular head dim'
        self.cluster_shape_mn = (1, 1)
        assert self.arch.is_family_of(p206_Arch.sm_90a), 'Only SM 9.x is supported'

    def _get_smem_layout_atom(self):
        sQ_layout_atom = p206_warpgroup.make_smem_layout_atom(p206_sm90_utils_basic.get_smem_layout_atom(p206_LayoutEnum.ROW_MAJOR, self.dtype, self.tile_hdim), self.dtype)
        sK_layout_atom = sQ_layout_atom
        sV_layout_atom = p206_warpgroup.make_smem_layout_atom(p206_sm90_utils_basic.get_smem_layout_atom(p206_LayoutEnum.ROW_MAJOR, self.dtype, self.tile_hdimv), self.dtype)
        sO_layout_atom = p206_warpgroup.make_smem_layout_atom(p206_sm90_utils_basic.get_smem_layout_atom(p206_LayoutEnum.ROW_MAJOR, self.o_dtype, self.tile_hdimv), self.o_dtype)
        if not self.mma_pv_is_rs:
            sP_layout_atom = p206_warpgroup.make_smem_layout_atom(p206_sm90_utils_basic.get_smem_layout_atom(p206_LayoutEnum.ROW_MAJOR, self.dtype, self.tile_n), self.dtype)
        else:
            sP_layout_atom = None
        return (sQ_layout_atom, sK_layout_atom, sV_layout_atom, sO_layout_atom, sP_layout_atom)

    def _get_tiled_mma(self):
        self.atom_layout_n = 2 if self.tile_hdim > 256 or self.tile_hdimv > 256 else 1
        tiled_mma_qk = p206_sm90_utils_basic.make_trivial_tiled_mma(self.dtype, self.dtype, p206_warpgroup.OperandMajorMode.K, p206_warpgroup.OperandMajorMode.K, Float32, atom_layout_mnk=(self.tile_m // 64, self.atom_layout_n, 1), tiler_mn=(64, self.tile_n))
        tiled_mma_pv = p206_sm90_utils_basic.make_trivial_tiled_mma(self.dtype, self.dtype, p206_warpgroup.OperandMajorMode.K, p206_warpgroup.OperandMajorMode.K if self.native_fp8 else p206_warpgroup.OperandMajorMode.MN, Float32, atom_layout_mnk=(self.tile_m // 64, self.atom_layout_n, 1), tiler_mn=(64, min(256, self.tile_hdimv)), a_source=p206_warpgroup.OperandSource.RMEM if self.mma_pv_is_rs else p206_warpgroup.OperandSource.SMEM)
        return (tiled_mma_qk, tiled_mma_pv)

    @cute.jit
    def _transpose_v_ldsm_native_fp8(self, sVLoad: cute.Tensor, sV: cute.Tensor, tidx: Int32, stage_idx: Int32) -> None:
        assert self.tile_n % 32 == 0 and self.tile_hdimv % 32 == 0
        num_warps = const_expr(self.v_transpose_warps)
        units_d = const_expr(self.tile_hdimv // 32)
        num_units = const_expr(self.tile_n // 16 * units_d)
        first_warp = const_expr(self.num_threads_per_warp_group // cute.arch.WARP_SIZE - num_warps)
        warp_idx = cute.arch.make_warp_uniform(tidx // cute.arch.WARP_SIZE) - first_warp
        lane = cute.arch.lane_idx()
        s2r_tiled_copy_vload = cute.make_tiled_copy(cute.make_copy_atom(p206_warp.LdMatrix8x8x16bOp(transpose=True, num_matrices=4), sVLoad.element_type), cute.make_layout(((4, 8), (2, 2, 2, 2)), stride=((2, 32), (16, 1, 8, 256))), (16, 32))
        r2s_tiled_copy_v = cute.make_tiled_copy(cute.make_copy_atom(p206_warp.StMatrix8x8x16bOp(transpose=False, num_matrices=4), sV.element_type), cute.make_layout(((4, 8), (4, 2, 2)), stride=((4, 32), (1, 16, 256))), (16, 32))
        tTranssVLoad = s2r_tiled_copy_vload.get_slice(lane).partition_S(sVLoad[None, None, stage_idx])
        tTranssV = r2s_tiled_copy_v.get_slice(lane).partition_D(sV[None, None, stage_idx])
        for i in cutlass.range_constexpr(cute.ceil_div(num_units, 2 * num_warps)):
            for w in cutlass.range_constexpr(num_warps):
                unit_a = 2 * i * num_warps + w
                unit_b = unit_a + num_warps
                if const_expr(unit_a < num_units):
                    if warp_idx == w:
                        tTransrVLoad_a = cute.make_rmem_tensor_like(tTranssVLoad[None, 0, 0])
                        cute.copy(s2r_tiled_copy_vload, tTranssVLoad[None, unit_a // units_d, unit_a % units_d], tTransrVLoad_a)
                        if const_expr(unit_b < num_units):
                            tTransrVLoad_b = cute.make_rmem_tensor_like(tTranssVLoad[None, 0, 0])
                            cute.copy(s2r_tiled_copy_vload, tTranssVLoad[None, unit_b // units_d, unit_b % units_d], tTransrVLoad_b)
                            self._stsm_v_native_fp8(r2s_tiled_copy_v, tTransrVLoad_a, tTranssV[None, unit_a // units_d, unit_a % units_d])
                            self._stsm_v_native_fp8(r2s_tiled_copy_v, tTransrVLoad_b, tTranssV[None, unit_b // units_d, unit_b % units_d])
                        else:
                            self._stsm_v_native_fp8(r2s_tiled_copy_v, tTransrVLoad_a, tTranssV[None, unit_a // units_d, unit_a % units_d])

    @cute.jit
    def _stsm_v_native_fp8(self, r2s_tiled_copy_v: cute.TiledCopy, tTransrVLoad: cute.Tensor, tTranssV: cute.Tensor) -> None:
        tTransrV = cute.make_rmem_tensor_like(tTranssV)
        rVLoad, rV = (cute.recast_tensor(tTransrVLoad, Int32), cute.recast_tensor(tTransrV, Int32))
        for j in cutlass.range_constexpr(2):
            rV[2 * j] = cute.arch.prmt(rVLoad[2 * j], rVLoad[2 * j + 1], Int32(25632))
            rV[2 * j + 1] = cute.arch.prmt(rVLoad[2 * j], rVLoad[2 * j + 1], Int32(30001))
        cute.copy(r2s_tiled_copy_v, tTransrV, tTranssV)

    def _get_shared_storage_cls(self):
        q_storage_elems = cute.cosize(self.sQ_layout)
        if const_expr(self.native_fp8):
            q_storage_elems = max(q_storage_elems, (cute.cosize(self.sO_layout) * self.o_dtype.width + self.dtype.width - 1) // self.dtype.width)
        sQ_struct = cute.struct.Align[cute.struct.MemRange[self.dtype, q_storage_elems], self.buffer_align_bytes]
        sK_struct, sV_struct = [cute.struct.Align[cute.struct.MemRange[self.dtype, cute.cosize(layout)], self.buffer_align_bytes] for layout in (self.sK_layout, self.sV_layout)]
        cosize_sQV = max(cute.cosize(self.sQ_layout), cute.cosize(self.sV_layout))
        sQV_struct = cute.struct.Align[cute.struct.MemRange[self.dtype, cosize_sQV], 1024]
        cosize_sP = cute.cosize(self.sP_layout) if const_expr(self.sP_layout is not None) else 0
        sP_struct = cute.struct.Align[cute.struct.MemRange[self.dtype, cosize_sP], 1024]
        mbar_ptr_Q_struct = cute.struct.MemRange[cutlass.Int64, 1 * 2]
        mbar_ptr_K_struct = cute.struct.MemRange[cutlass.Int64, self.num_stages * 2]
        mbar_ptr_V_struct = cute.struct.MemRange[cutlass.Int64, self.num_stages * 2]
        if const_expr(self.fp8_kv_dequant):
            sStage_struct = cute.struct.Align[cute.struct.MemRange[self.kv_dtype, cute.cosize(self.sStage_layout)], self.buffer_align_bytes]
            mbar_ptr_Stage_struct = cute.struct.MemRange[cutlass.Int64, 1 * 2]

            @cute.struct
            class SharedStorageQKVDequant:
                mbar_ptr_Q: mbar_ptr_Q_struct
                mbar_ptr_K: mbar_ptr_K_struct
                mbar_ptr_V: mbar_ptr_V_struct
                mbar_ptr_Stage: mbar_ptr_Stage_struct
                sV: sV_struct
                sQ: sQ_struct
                sK: sK_struct
                sStage: sStage_struct
            return SharedStorageQKVDequant
        if const_expr(self.native_fp8):
            sVLoad_struct = cute.struct.Align[cute.struct.MemRange[self.dtype, cute.cosize(self.sV_load_layout)], self.buffer_align_bytes]
            mbar_ptr_VLoad_struct = cute.struct.MemRange[cutlass.Int64, self.num_stages * 2]

            @cute.struct
            class SharedStorageQKVNativeFp8:
                mbar_ptr_Q: mbar_ptr_Q_struct
                mbar_ptr_K: mbar_ptr_K_struct
                mbar_ptr_V: mbar_ptr_V_struct
                mbar_ptr_VLoad: mbar_ptr_VLoad_struct
                sV: sV_struct
                sVLoad: sVLoad_struct
                sQ: sQ_struct
                sK: sK_struct
                sP: sP_struct
            return SharedStorageQKVNativeFp8

        @cute.struct
        class SharedStorageQKV:
            mbar_ptr_Q: mbar_ptr_Q_struct
            mbar_ptr_K: mbar_ptr_K_struct
            mbar_ptr_V: mbar_ptr_V_struct
            sV: sV_struct
            sQ: sQ_struct
            sK: sK_struct
            sP: sP_struct

        @cute.struct
        class SharedStorageSharedQV:
            mbar_ptr_Q: mbar_ptr_Q_struct
            mbar_ptr_K: mbar_ptr_K_struct
            mbar_ptr_V: mbar_ptr_V_struct
            sQ: sQV_struct
            sK: sK_struct
            sP: sP_struct
        return SharedStorageQKV if const_expr(not self.Q_in_regs) else SharedStorageSharedQV

    @cute.jit
    def __call__(self, mQ: cute.Tensor, mK: cute.Tensor, mV: cute.Tensor, mO: cute.Tensor, mLSE: p206_Optional[cute.Tensor], softmax_scale: Float32, mCuSeqlensQ: p206_Optional[cute.Tensor]=None, mCuSeqlensK: p206_Optional[cute.Tensor]=None, mSeqUsedQ: p206_Optional[cute.Tensor]=None, mSeqUsedK: p206_Optional[cute.Tensor]=None, mDynamicCausal: p206_Optional[cute.Tensor]=None, mPageTable: p206_Optional[cute.Tensor]=None, window_size_left: Int32 | int | None=None, window_size_right: Int32 | int | None=None, learnable_sink: p206_Optional[cute.Tensor]=None, blocksparse_tensors: p206_Optional[p206_BlockSparseTensors]=None, aux_data: p206_AuxData=p206_AuxData(), descale_tensors=None, output_scale: p206_Optional[cute.Tensor]=None, mCuTotalMBlocks: p206_Optional[cute.Tensor]=None, mCuTotalSplitsMBlocks: p206_Optional[cute.Tensor]=None, stream: p206_cuda.CUstream=None):
        if const_expr(self.native_fp8):
            assert all((t.element_type == p206_Float8E4M3FN for t in (mQ, mK, mV))), 'native_fp8 requires E4M3 Q, K, and V'
            assert mO.element_type == (Float32 if self.is_split_kv else self.o_dtype), 'native_fp8 writes the configured output dtype, or FP32 SplitKV partials'
            assert mLSE is None or mLSE.element_type == Float32
            assert all((t is None or t.element_type == Int32 for t in (mCuSeqlensQ, mCuSeqlensK, mSeqUsedQ, mSeqUsedK)))
        elif const_expr(not self.fp8_kv_dequant):
            self._check_type(*(t.element_type if t is not None else None for t in (mQ, mK, mV, mO, mLSE, mCuSeqlensQ, mCuSeqlensK, mSeqUsedQ, mSeqUsedK)), is_split_kv=self.is_split_kv)
        else:
            assert self.dtype == p206_Float16, 'fp8_kv_dequant computes in fp16'
            assert mQ.element_type in (p206_Float16, p206_BFloat16), 'fp8_kv_dequant expects fp16 or bf16 Q'
            if const_expr(self.is_split_kv):
                assert mO.element_type == Float32, 'fp8_kv_dequant SplitKV expects Float32 O (partial accumulator)'
            else:
                assert mO.element_type in (p206_Float16, p206_BFloat16), 'fp8_kv_dequant expects fp16 or bf16 O'
        self.q_dtype = mQ.element_type
        if const_expr(self.fp8_kv_dequant):
            self.o_dtype = mO.element_type if const_expr(not self.is_split_kv) else self.dtype
        self.varlen_q = mCuSeqlensQ is not None or mSeqUsedQ is not None
        mQ, mK, mV, mO = [p206_assume_tensor_aligned(t) for t in (mQ, mK, mV, mO)]
        Q_layout_transpose = [1, 3, 2, 0] if const_expr(mCuSeqlensQ is None) else [0, 2, 1]
        mQ = p206_layout_utils.select(mQ, Q_layout_transpose)
        num_splits = Int32(1)
        if const_expr(not self.is_split_kv):
            O_layout_transpose = [1, 3, 2, 0] if const_expr(mCuSeqlensQ is None) else [0, 2, 1]
            LSE_layout_transpose = [2, 1, 0] if const_expr(mCuSeqlensQ is None) else [1, 0]
        else:
            O_layout_transpose = [2, 4, 3, 1, 0] if const_expr(mCuSeqlensQ is None) else [1, 3, 2, 0]
            LSE_layout_transpose = [3, 2, 1, 0] if const_expr(mCuSeqlensQ is None) else [2, 1, 0]
            num_splits = mO.shape[0]
        mO = p206_layout_utils.select(mO, O_layout_transpose)
        KV_layout_transpose = [1, 3, 2, 0] if const_expr(mCuSeqlensK is None) else [0, 2, 1]
        mK, mV = [p206_layout_utils.select(t, KV_layout_transpose) for t in (mK, mV)]
        mLSE = p206_layout_utils.select(mLSE, LSE_layout_transpose) if const_expr(mLSE is not None) else None
        tiled_mma_qk, tiled_mma_pv = self._get_tiled_mma()
        self.num_mma_threads = tiled_mma_qk.size
        self.num_threads_per_warp_group = 128
        self.num_wg_mma = self.num_mma_threads // self.num_threads_per_warp_group
        assert self.num_wg_mma in [1, 2, 3]
        self.num_threads = self.num_threads_per_warp_group * (self.num_wg_mma + 1)
        self.num_producer_threads = 32
        self.num_Q_load_threads = self.num_threads_per_warp_group
        self.num_epilogue_threads = self.num_mma_threads
        self.num_mma_regs, self.num_producer_regs = {1: (256, 56), 2: (240, 24), 3: (160, 32)}[self.num_wg_mma]
        self.use_block_sparsity = cutlass.const_expr(blocksparse_tensors is not None)
        assert not (self.native_fp8 and self.use_block_sparsity), 'SM90 native FP8 does not support block sparsity'
        self.transpose_v_in_producer = self.native_fp8
        self.dedicated_kv_load_warp = self.transpose_v_in_producer and self.use_tma_KV
        self.v_transpose_warps = 3 if self.dedicated_kv_load_warp else 4
        self.use_scheduler_barrier = self.num_wg_mma >= 2 and self.tile_hdim <= 128 if const_expr(self.intra_wg_overlap) else self.num_wg_mma == 2
        self.use_tma_Q = self.arch >= p206_Arch.sm_90 and (not (self.pack_gqa and self.tile_m % self.qhead_per_kvhead != 0))
        self.use_tma_O = self.use_tma_Q and (not self.is_split_kv)
        if const_expr(self.num_wg_mma == 2 and (not self.use_tma_Q or not self.use_tma_KV)):
            self.num_mma_regs, self.num_producer_regs = (224, 40)
        if const_expr(self.transpose_v_in_producer and self.num_wg_mma == 2):
            self.num_producer_regs = 40
            self.num_mma_regs = 232 if const_expr(self.use_tma_Q and self.use_tma_KV) else 224
        if const_expr(self.transpose_v_in_producer and self.num_wg_mma == 3):
            self.num_mma_regs, self.num_producer_regs = (152, 56)
        if const_expr(self.ctas_per_sm == 2):
            assert self.num_wg_mma == 1, 'two CTAs per SM need a single MMA warpgroup'
            self.num_mma_regs, self.num_producer_regs = (200, 56)
        self.rescale_O_before_gemm = self.tile_hdimv > 128 and self.intra_wg_overlap
        self.p_shared_across_wg = self.atom_layout_n == 2
        self._setup_attributes()
        sK_dtype = self.dtype if const_expr(self.fp8_kv_dequant) else mK.element_type
        sV_dtype = self.dtype if const_expr(self.fp8_kv_dequant) else mV.element_type
        self.sQ_layout, self.sK_layout, self.sV_layout, self.sO_layout = [p206_sm90_utils.make_smem_layout(dtype, layout_enum, shape, stage) for dtype, layout_enum, shape, stage in [(self.q_dtype, p206_LayoutEnum.ROW_MAJOR, (self.tile_m, self.tile_hdim), None), (sK_dtype, p206_LayoutEnum.ROW_MAJOR, (self.tile_n, self.tile_hdim), self.num_stages), (sV_dtype, p206_LayoutEnum.COL_MAJOR if self.native_fp8 else p206_LayoutEnum.ROW_MAJOR, (self.tile_n, self.tile_hdimv), self.num_stages), (self.o_dtype, p206_LayoutEnum.ROW_MAJOR, (self.tile_m, self.tile_hdimv), None)]]
        self.sV_load_layout = p206_sm90_utils.make_smem_layout(sV_dtype, p206_LayoutEnum.ROW_MAJOR, (self.tile_n, self.tile_hdimv), self.num_stages) if const_expr(self.native_fp8) else self.sV_layout
        self.sStage_layout = None
        if const_expr(self.fp8_kv_dequant):
            self.sStage_layout = p206_sm90_utils.make_smem_layout(self.kv_dtype, p206_LayoutEnum.ROW_MAJOR, (self.tile_n, self.tile_hdim), 1)
        self.sP_layout = None
        if const_expr(not self.mma_pv_is_rs):
            self.sP_layout = p206_sm90_utils.make_smem_layout(mV.element_type, p206_LayoutEnum.ROW_MAJOR, (self.tile_m, self.tile_n))
        SharedStorage = self._get_shared_storage_cls()
        mQ_og, mO_og = (mQ, mO)
        if const_expr(self.pack_gqa):
            nheads_kv = mK.shape[2]
            mQ = p206_pack_gqa_layout(mQ, self.qhead_per_kvhead, nheads_kv, head_idx=2)
            mO = p206_pack_gqa_layout(mO, self.qhead_per_kvhead, nheads_kv, head_idx=2)
            if const_expr(mLSE is not None):
                mLSE = p206_pack_gqa_layout(mLSE, self.qhead_per_kvhead, nheads_kv, head_idx=1)
        gmem_tiled_copy_Q = p206_cpasync.CopyBulkTensorTileG2SOp()
        gmem_tiled_copy_KV = p206_cpasync.CopyBulkTensorTileG2SOp()
        gmem_tiled_copy_O = p206_cpasync.CopyBulkTensorTileS2GOp()
        self.tma_copy_bytes = {name: cute.size_in_bytes(mX.element_type, cute.select(layout, mode=[0, 1])) for name, mX, layout in [('Q', mQ, self.sQ_layout), ('K', mK, self.sK_layout), ('V', mV, self.sV_load_layout)]}
        make_tiled_tma_atom_fn = p206_partial(p206_make_packgqa_tiled_tma_atom, qhead_per_kvhead=self.qhead_per_kvhead, head_idx=2) if const_expr(self.pack_gqa) else p206_cpasync.make_tiled_tma_atom
        tma_atom_Q, tma_tensor_Q = (None, None)
        if const_expr(self.use_tma_Q):
            tma_atom_Q, tma_tensor_Q = make_tiled_tma_atom_fn(gmem_tiled_copy_Q, mQ_og if const_expr(self.pack_gqa) else mQ, self.sQ_layout, (self.tile_m, self.tile_hdim))
        tma_atom_K, tma_tensor_K = (None, None)
        tma_atom_V, tma_tensor_V = (None, None)
        if const_expr(self.use_tma_KV):
            sK_tma_box = cute.select(self.sStage_layout if const_expr(self.fp8_kv_dequant) else self.sK_layout, mode=[0, 1])
            sV_tma_box = cute.select(self.sStage_layout if const_expr(self.fp8_kv_dequant) else self.sV_load_layout, mode=[0, 1])
            tma_box_n = self.tile_n
            if const_expr(self.tma_box_n is not None):
                tma_box_n = self.tma_box_n
                sK_tma_box = cute.composition(sK_tma_box, (tma_box_n, self.tile_hdim))
                sV_tma_box = cute.composition(sV_tma_box, (tma_box_n, self.tile_hdimv))
            tma_atom_K, tma_tensor_K = p206_cpasync.make_tiled_tma_atom(gmem_tiled_copy_KV, mK, sK_tma_box, (tma_box_n, self.tile_hdim), 1)
