    @cute.jit
    def load_native_fp8(self, mQ: cute.Tensor, mK: cute.Tensor, mV: cute.Tensor, sQ: cute.Tensor, sK: cute.Tensor, sVLoad: cute.Tensor, sV: cute.Tensor, tma_atom_Q: p206_Optional[cute.CopyAtom], tma_atom_K: p206_Optional[cute.CopyAtom], tma_atom_V: p206_Optional[cute.CopyAtom], pipeline_k: p206_pipeline.PipelineAsync, pipeline_vload: p206_pipeline.PipelineAsync, pipeline_v: p206_pipeline.PipelineAsync, pipeline_q: p206_pipeline.PipelineAsync, gmem_tiled_copy_Q: cute.TiledCopy, mPageTable: p206_Optional[cute.Tensor], block_info: p206_BlockInfo, SeqlenInfoCls: p206_Callable, TileSchedulerCls: p206_Callable, num_splits: Int32=Int32(1)):
        warp_idx_in_wg = cute.arch.make_warp_uniform(cute.arch.warp_idx()) % 4
